using System.Runtime.InteropServices;

namespace CatalogSvc;

public class ProductCatalog
{
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, decimal> _prices = new(StringComparer.OrdinalIgnoreCase);

    // Reverse index: category → set of product codes (O(1) lookup by category)
    private readonly Dictionary<string, HashSet<string>> _productsByCategory =
        new(StringComparer.OrdinalIgnoreCase);

    public void AddProduct(string code, string category, decimal price)
    {
        // Remove from old category's reverse index if re-categorizing
        ref var existingCategory = ref CollectionsMarshal.GetValueRefOrAddDefault(
            _categories, code, out bool existed);

        if (existed && existingCategory is not null
            && _productsByCategory.TryGetValue(existingCategory, out var oldSet))
        {
            oldSet.Remove(code);
        }

        existingCategory = category;
        _prices[code] = price;

        ref var categorySet = ref CollectionsMarshal.GetValueRefOrAddDefault(
            _productsByCategory, category, out bool categoryExisted);
        categorySet ??= new(StringComparer.OrdinalIgnoreCase);
        categorySet.Add(code);
    }

    public string? GetCategory(string code)
        => _categories.TryGetValue(code, out var cat) ? cat : null;

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        decimal total = 0m;
        foreach (var code in codes)
        {
            if (_prices.TryGetValue(code, out var price))
                total += price;
        }
        return total;
    }

    public List<string> GetProductsByCategory(string category)
    {
        if (_productsByCategory.TryGetValue(category, out var set))
            return [.. set];

        return [];
    }
}

